tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
Write-Output '=== Fish-under-sea repos (19) ==='
try { (Invoke-RestMethod 'https://api.github.com/users/Fish-under-sea/repos?per_page=100&sort=pushed' -Headers $h -TimeoutSec 25) | Select-Object name,description,pushed_at | Format-Table -AutoSize -Wrap | Out-String -Width 200 } catch { Write-Output "FAILED: $($_.Exception.Message)" }
